"""
Data models for the final Compliance Report.

Includes executive summaries, structured findings, missing data checklists,
and mandatory legal/engineering disclaimers.
"""

from __future__ import annotations

import uuid
from datetime import datetime, timezone
from enum import Enum

from pydantic import BaseModel, Field

from nirmantra_ai.rag.models import GroundedFinding

MANDATORY_LEGAL_DISCLAIMER = (
    "DISCLAIMER & LEGAL LIMITATION: This document is an automated AI-assisted preliminary "
    "compliance advisory report generated by NIRMAANTRA for informational and pre-screening purposes only. "
    "It does NOT constitute official building plan sanction, permit approval, structural fitness certification, "
    "or legal clearance under the Delhi Municipal Corporation Act, Delhi Development Act, or Unified Building Bye-Laws for Delhi 2016. "
    "All findings, calculations, and recommendations must be verified and endorsed by a licensed Architect "
    "registered with the Council of Architecture (COA) or an empanelled Structural Engineer before submission "
    "to MCD, DDA, NDMC, or Delhi Fire Service."
)


class OverallComplianceStatus(str, Enum):
    """Aggregate determination of building compliance."""

    COMPLIANT = "COMPLIANT"                         # All applicable rules passed conclusively
    NON_COMPLIANT = "NON_COMPLIANT"                 # One or more rules confirmed failed
    REQUIRES_REVIEW = "REQUIRES_REVIEW"             # Missing evidence or borderline findings


class ReportSummary(BaseModel):
    """Executive summary of the compliance analysis."""

    overall_status: OverallComplianceStatus
    total_requirements_checked: int
    passed_count: int
    failed_count: int
    needs_review_count: int
    not_applicable_count: int
    compliance_score_percent: float = Field(
        description="Percentage of applicable, conclusive checks that passed.",
    )


class ComplianceReport(BaseModel):
    """The master compliance report artifact produced by Nirmantra AI."""

    report_id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    generated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    project_name: str = "Unnamed Project"
    location_address: str | None = None
    source_document: str | None = None
    jurisdiction: str = "Delhi NCT, India"

    summary: ReportSummary
    findings: list[GroundedFinding] = Field(default_factory=list)
    missing_information_checklist: list[str] = Field(default_factory=list)
    actionable_recommendations: list[str] = Field(default_factory=list)

    disclaimer: str = Field(default=MANDATORY_LEGAL_DISCLAIMER)

    @property
    def is_fully_compliant(self) -> bool:
        return self.summary.overall_status == OverallComplianceStatus.COMPLIANT
